async function refresh(silent=false){
  $('#loadState').textContent='加载中…';
  try{
    const suffix=selectedBoardId?`?board_id=${selectedBoardId}`:'';
    state=await api('/api/bootstrap'+suffix);selectedBoardId=state.board?.id||null;
    const resolution=FlowboardViewState.resolve({views:state.saved_views||[],effectiveDefaultId:state.effective_default_view_id,activeViewId,urlExplicit:urlViewExplicit,adHoc:adHocQuery,blockedLatch});if(resolution.kind==='view'){activeViewId=resolution.view.id;activePresentation=resolution.view;viewType=resolution.view.view_type;activeQuery=FlowboardViewState.queryFor(resolution,activeQuery)}else if(resolution.kind==='blocked'){blockedLatch=true;activePresentation={blocked:true};activeViewId=null;toast('视图不可用，已阻止执行');syncUrl()}else if(resolution.kind==='synthetic'){activePresentation=null;viewType='table';localPresentation=FlowboardViewState.defaultPresentation('table',state.fields||[]);activeQuery={version:1,filter:{op:'and',children:[]},sort:[]}}
    if(state.board){const result=activePresentation?.blocked?{tasks:[],total:0}:await api(`/api/boards/${state.board.id}/query`,'POST',activeQuery);const byGroup=new Map(state.groups.map(group=>[group.id,group]));state.groups.forEach(group=>group.tasks=[]);result.tasks.forEach(task=>byGroup.get(task.group_id)?.tasks.push(task));state.query_total=result.total}
    $('#currentUser').innerHTML=`${avatar(state.current_user)}<span>${esc(state.current_user.name)}</span>`;
    renderSidebar();renderBoard();updateCapabilities();updateI12Chrome();$('#loadState').textContent='刚刚同步';
  }catch(error){$('#loadState').textContent='加载失败';const failure=FlowboardViewState.refreshFailure(error.status,silent);if(failure.identityExpired){csrfToken='';state.current_user=null;viewTransition('identity');showLogin('登录已过期，请重新登录')}else if(failure.report)showError(error)}
}
