function renderCalendar(){const field=activeField(presentationSource()?.date_field_id);if(!field){$('#board').innerHTML='<div class="empty-state">日历日期字段不可用。</div>';return}const model=FlowboardViews.calendar(field,allTasks(),calendarCursor.getFullYear(),calendarCursor.getMonth());$('#board').innerHTML=`<div class="calendar-toolbar"><button data-month="-1">‹</button><button data-month="today">今天</button><strong>${calendarCursor.getFullYear()} 年 ${calendarCursor.getMonth()+1} 月</strong><button data-month="1">›</button></div><div class="calendar-week">${'日一二三四五六'.split('').map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${model.cells.map(cell=>`<section class="calendar-day ${cell.outside?'outside':''}" data-date-drop="${cell.iso}"><b>${cell.day}</b>${cell.tasks.map(calendarCard).join('')}</section>`).join('')}</div>${model.outside.length?`<section class="undated"><h3>其他月份</h3>${model.outside.map(calendarCard).join('')}</section>`:''}<section class="undated" data-date-drop=""><h3>无日期 / 待修正</h3>${model.undated.map(calendarCard).join('')||'<div class="empty-state compact">没有无日期任务</div>'}</section>`;bindFieldDrops(field);document.querySelectorAll('[data-month]').forEach(button=>button.onclick=()=>{if(button.dataset.month==='today')calendarCursor=new Date();else calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+Number(button.dataset.month),1);syncUrl();renderBoard()})}
let scheduleRequest=0;
function schedulePresentation(){return presentationSource()||FlowboardViewState.defaultPresentation(viewType,state.fields||[])}
async function saveSchedulePresentation(next){localPresentation=next;if(activePresentation?.can_update){const updated=await api(`/api/views/${activePresentation.id}`,'PATCH',{version:activePresentation.version,presentation:next});activePresentation={...activePresentation,...updated,presentation:next}}renderBoard()}
async function editSchedule(taskId,start,end,delta=0,mode='move'){const task=findTask(taskId);if(!task)return;const nextStart=delta?(mode==='resize-start'?FlowboardSchedule.addDays(start,delta):mode==='resize-end'?start:FlowboardSchedule.addDays(start,delta)):prompt('开始日期 YYYY-MM-DD',start);if(nextStart===null)return;const nextEnd=delta?(mode==='resize-end'?FlowboardSchedule.addDays(end,delta):mode==='resize-start'?end:FlowboardSchedule.addDays(end,delta)):prompt('结束日期 YYYY-MM-DD',end);if(nextEnd===null)return;const policy=confirm('同时将较早的直接后置任务推到当前排期来源的新结束日？')?'push_successors_once':'none';const versions={};if(policy==='push_successors_once'){const model=window.currentScheduleModel||{};(model.dependencies||[]).filter(edge=>edge.predecessor_id===taskId).forEach(edge=>{const successor=findTask(edge.successor_id);if(successor)versions[String(successor.id)]=successor.version})}try{interactionLocked=true;await api(`/api/tasks/${taskId}/schedule`,'POST',{version:task.version,board_version:state.board.version,source:schedulePresentation().source,start:nextStart,end:nextEnd,dependency_policy:policy,successor_versions:versions});await refresh();toast('排期已更新')}catch(error){showError(error)}finally{interactionLocked=false}}
function bindSchedule(model,layout){if(!canWrite())document.querySelectorAll('[data-schedule-edit]').forEach(button=>button.remove());document.querySelectorAll('[data-schedule-task]').forEach(row=>row.onclick=event=>{if(!event.target.closest('button,.schedule-bar'))openTask(+row.dataset.scheduleTask)});document.querySelectorAll('[data-schedule-edit]').forEach(button=>button.onclick=event=>{event.stopPropagation();editSchedule(+button.dataset.scheduleEdit,button.dataset.start,button.dataset.end)});document.querySelectorAll('[data-schedule-bar]').forEach(bar=>{bar.onclick=event=>event.stopPropagation();bar.onpointerdown=event=>{if(!canWrite()||matchMedia('(pointer:coarse)').matches)return;event.preventDefault();event.stopPropagation();const taskId=+bar.dataset.scheduleBar,startX=event.clientX,px=FlowboardSchedule.SCALE_PX[model.scale]||12,mode=event.offsetX<7?'resize-start':event.offsetX>bar.clientWidth-7?'resize-end':'move';interactionLocked=true;document.onpointerup=async end=>{document.onpointerup=null;const delta=Math.round((end.clientX-startX)/px);interactionLocked=false;if(delta)await editSchedule(taskId,bar.dataset.start,bar.dataset.end,delta,mode)}}});$('#scheduleScale').onchange=event=>saveSchedulePresentation({...schedulePresentation(),scale:event.target.value}).catch(showError);$('#scheduleSource').onchange=event=>{const value=event.target.value;saveSchedulePresentation({...schedulePresentation(),source:value==='fixed'?{kind:'fixed'}:{kind:'dynamic',id:Number(value)}}).catch(showError)};const today=document.querySelector('[data-today]'),scroll=document.querySelector('.schedule-scroll');if(today&&scroll)scroll.scrollLeft=Math.max(0,today.offsetLeft-scroll.clientWidth/2)}
async function renderSchedule(){const request=++scheduleRequest,presentation=schedulePresentation();$('#board').innerHTML='<div class="empty-state">加载排期…</div>';try{const model=await api(`/api/boards/${state.board.id}/schedule`,'POST',{query:activeQuery,presentation});if(request!==scheduleRequest||!['timeline','gantt'].includes(viewType))return;window.currentScheduleModel=model;const layout=FlowboardSchedule.layout(model.tasks,model.bounds,model.scale),byId=new Map(layout.map((item,index)=>[item.id,{...item,index}])),ticks=FlowboardSchedule.ticks(model.bounds,model.scale),critical=new Set(model.critical_path?.task_ids||[]),px=FlowboardSchedule.SCALE_PX[model.scale]||12,width=Math.max(720,(model.bounds?.span_days||30)*px+40),today=model.bounds?FlowboardSchedule.diffDays(model.bounds.start,new Date().toISOString().slice(0,10))*px:null;const fields=(state.fields||[]).filter(field=>field.is_active&&['date','timeline'].includes(field.field_type));const sourceOptions=`<option value="fixed">固定开始/截止日期</option>${fields.map(field=>`<option value="${field.id}" ${presentation.source?.id===field.id?'selected':''}>${esc(field.name)}</option>`).join('')}`;const lines=(model.dependencies||[]).map(edge=>{const a=byId.get(edge.predecessor_id),b=byId.get(edge.successor_id);if(!a||!b)return'';const x1=a.left+a.width,x2=b.left,y1=a.index*44+22,y2=b.index*44+22;return`<path d="M${x1} ${y1} C${x1+18} ${y1},${x2-18} ${y2},${x2} ${y2}"/>`}).join('');$('#board').innerHTML=`<div class="schedule-toolbar"><select id="scheduleSource">${sourceOptions}</select><select id="scheduleScale"><option value="day">日</option><option value="week">周</option><option value="month">月</option></select><button class="tool-btn" onclick="document.querySelector('[data-today]')?.scrollIntoView({inline:'center'})">今天</button><small>${model.total} 项 · 上限 ${model.limit}${model.critical_path?.blocked?' · 依赖循环，关键路径已停用':''}</small></div><div class="schedule-shell"><div class="schedule-labels">${layout.map(item=>`<div data-schedule-task="${item.id}" style="padding-left:${item.parent_id?18:8}px">${item.parent_id?'↳ ':''}<span>${esc(item.title)}</span>${canWrite()?`<button data-schedule-edit="${item.id}" data-start="${item.start}" data-end="${item.end}">编辑</button>`:''}</div>`).join('')}</div><div class="schedule-scroll"><div class="schedule-canvas" style="width:${width}px;height:${Math.max(80,layout.length*44+32)}px">${ticks.map(tick=>`<i class="schedule-tick" style="left:${tick.left}px"><b>${tick.date}</b></i>`).join('')}${today!==null?`<i class="schedule-today" data-today style="left:${today}px"></i>`:''}<svg class="schedule-links" width="${width}" height="${layout.length*44}">${lines}</svg>${layout.map((item,index)=>`<button class="schedule-bar ${critical.has(item.id)?'critical':''} ${viewType==='gantt'&&item.milestone?'milestone':''}" data-schedule-bar="${item.id}" data-start="${item.start}" data-end="${item.end}" title="${esc(item.title)} · ${item.start} → ${item.end}" style="left:${item.left}px;top:${index*44+10}px;width:${item.width}px"></button>`).join('')}</div></div></div>${model.unscheduled.length?`<section class="undated"><h3>未排期 / 日期无效</h3>${model.unscheduled.map(item=>`<button class="view-card" data-schedule-edit="${item.id}" data-start="${new Date().toISOString().slice(0,10)}" data-end="${new Date().toISOString().slice(0,10)}">${esc(item.title)}</button>`).join('')}</section>`:''}`;$('#scheduleScale').value=model.scale;bindSchedule(model,layout);updateCapabilities()}catch(error){if(request===scheduleRequest){$('#board').innerHTML=`<div class="empty-state">${esc(error.message)}</div>`;showError(error)}}}
function bindFieldDrops(field,columns=[]){if(field.field_type==='timeline')return;let mutate;if(viewType==='kanban')mutate=async(task,selected,value,meta)=>{interactionLocked=true;try{await api(`/api/tasks/${task.id}/kanban-move`,'POST',FlowboardViews.kanbanPatch(task,state.board.version,selected,value,meta.anchorTaskId,meta.placement));await refresh();toast('Kanban 顺序已保存')}catch(error){showError(error);await refresh(true)}finally{interactionLocked=false}};else mutate=FlowboardViews.controller({api,refresh,lock:value=>interactionLocked=value,fail:showError});FlowboardViews.bindDrops(document,{field,columns,canWrite:canWrite(),findTask,mutate})}
async function renderChart(){const presentation=presentationSource()||FlowboardViewState.defaultPresentation('chart',state.fields||[]);$('#board').innerHTML='<div class="empty-state">加载图表…</div>';try{const model=await api(`/api/boards/${state.board.id}/aggregate`,'POST',{query:activeQuery,spec:presentation});if(viewType!=='chart')return;$('#board').innerHTML=`<section class="chart-panel"><header><h2>${esc(activePresentation?.name||'看板图表')}</h2><select id="chartType"><option value="bar">柱状图</option><option value="line">折线图</option><option value="pie">饼图</option><option value="stacked_bar">堆叠柱状图</option></select></header>${FlowboardDashboard.chart(model,presentation.chart_type)}</section>`;$('#chartType').value=presentation.chart_type;$('#chartType').onchange=async event=>{const type=event.target.value,next={...presentation,chart_type:type,date_bucket:type==='line'?(presentation.date_bucket==='none'?'month':presentation.date_bucket):'none'};localPresentation=next;try{if(activePresentation?.can_update){const updated=await api(`/api/views/${activePresentation.id}`,'PATCH',{version:activePresentation.version,presentation:next});activePresentation={...activePresentation,...updated,presentation:next}}renderChart()}catch(error){showError(error)}}}catch(error){$('#board').innerHTML=`<div class="empty-state">${esc(error.message)}</div>`;showError(error)}}
function renderBoard(){viewType=activePresentation?.view_type||viewType;document.querySelectorAll('[data-view-type]').forEach(button=>button.classList.toggle('active',button.dataset.viewType===viewType));if(viewType==='kanban')renderKanban();else if(viewType==='calendar')renderCalendar();else if(['timeline','gantt'].includes(viewType))renderSchedule();else if(viewType==='chart')renderChart();else renderTable();$('#taskCount').textContent=state.query_total??allTasks().length;renderViews();updateCapabilities();bindResize();bindTaskSelection()}
function bindResize(){document.querySelectorAll('[data-resize]').forEach(handle=>handle.onpointerdown=event=>{if(activePresentation&&!activePresentation.can_update)return;interactionLocked=true;const source=presentationSource(),id=handle.dataset.resize,start=event.clientX,current=source?.widths?.[id]||(id==='title'?250:140);document.onpointermove=e=>{source.widths[id]=Math.max(80,Math.min(600,current+e.clientX-start));renderBoard()};document.onpointerup=async()=>{document.onpointermove=null;try{if(activePresentation){await api(`/api/views/${activePresentation.id}`,'PATCH',{version:activePresentation.version,presentation:source});await refresh(true)}}catch(error){showError(error)}finally{interactionLocked=false}}})}
function bindBoardEvents(){
  document.querySelectorAll('[data-task]').forEach(row=>{row.onclick=event=>{if(!event.target.closest('button'))openTask(+row.dataset.task)};row.ondragstart=()=>{draggedTask={taskId:+row.dataset.task,sourceGroupId:+row.dataset.group};row.classList.add('dragging')};row.ondragend=()=>{row.classList.remove('dragging');document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'))}});
  document.querySelectorAll('[data-group-drop]').forEach(group=>{group.ondragover=event=>{if(draggedTask){event.preventDefault();group.classList.add('drop-target')}};group.ondragleave=()=>group.classList.remove('drop-target');group.ondrop=event=>{event.preventDefault();group.classList.remove('drop-target');if(draggedTask)moveTask(draggedTask.taskId,+group.dataset.groupDrop)}});
  document.querySelectorAll('[data-add]').forEach(button=>button.onclick=()=>addTask(+button.dataset.add));
  document.querySelectorAll('[data-group-menu]').forEach(button=>button.onclick=()=>groupMenu(+button.dataset.groupMenu));
  document.querySelectorAll('[data-group-up]').forEach(button=>button.onclick=()=>moveGroup(+button.dataset.groupUp,-1));
  document.querySelectorAll('[data-group-down]').forEach(button=>button.onclick=()=>moveGroup(+button.dataset.groupDown,1));
  document.querySelectorAll('[data-task-menu]').forEach(button=>button.onclick=()=>taskMenu(+button.dataset.taskMenu));
}

