    document.querySelectorAll('[data-use-template]').forEach(button=>button.onclick=async()=>{const name=prompt('新看板名称','模板副本');if(!name)return;try{const created=await api(`/api/templates/${button.dataset.useTemplate}/instantiate`,'POST',{name});closeModal('listModal');selectedBoardId=created.id;viewTransition('board');await refresh();toast('模板已实例化')}catch(error){showError(error)}});
