function fileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('文件读取失败'));reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.readAsDataURL(file)})}
async function manageImport(){
  if(!state.board||!state.groups.length)return toast('请先创建分组');
  openList(`<h2>导入 CSV / XLSX</h2><p class="modal-subtitle">最多 1.5 MB、1000 行、100 列。公式、宏与外部链接会被拒绝。</p><label class="transfer-field">选择文件<input id="importFile" type="file" accept=".csv,.xlsx" /></label><button class="primary-btn" id="previewImportBtn">预览并映射</button><div id="importPreview"></div>`);
  let file,encoded;
  async function runPreview(sheet){
    try{
      const preview=await api(`/api/boards/${state.board.id}/imports/preview`,'POST',{filename:file.name,content_base64:encoded,board_version:state.board.version,...(sheet?{sheet}:{})});const supported=(state.fields||[]).filter(field=>!['person','link','timeline','file','relation','mirror','formula'].includes(field.field_type));const options='<option value="">跳过</option><option value="title">任务标题</option>'+supported.map(field=>`<option value="f:${field.id}">${esc(field.name)} (${esc(field.field_type)})</option>`).join('');const sheetPicker=preview.sheets.length>1?`<label class="transfer-field">工作表<select id="importSheet">${preview.sheets.map(name=>`<option ${name===preview.sheet?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`:'';
      $('#importPreview').innerHTML=`${sheetPicker}<p>${preview.row_count} 行 · ${esc(preview.format.toUpperCase())} · ${esc(preview.sheet)}</p>${preview.headers.map((header,index)=>{const inferred=preview.inferred[index]||{};return `<label class="mapping-row"><span>${esc(header)}</span><select data-map-column="${esc(header)}">${options}</select><small>推断 ${esc(inferred.inferred_type||'text')} · ${esc((inferred.samples||[]).join(' / ')||(preview.sample_rows[0]||[])[index]||'')}</small></label>`}).join('')}<label class="transfer-field">目标分组<select id="importGroup">${state.groups.map(group=>`<option value="${group.id}">${esc(group.name)}</option>`).join('')}</select></label><button class="primary-btn" id="commitImportBtn">确认导入</button>`;
      if($('#importSheet'))$('#importSheet').onchange=event=>runPreview(event.target.value);
      const first=document.querySelector('[data-map-column]');if(first)first.value='title';$('#commitImportBtn').onclick=async()=>{const mapping=[...document.querySelectorAll('[data-map-column]')].filter(select=>select.value).map(select=>({column:select.dataset.mapColumn,target:select.value==='title'?{kind:'core',key:'title'}:{kind:'dynamic',id:Number(select.value.slice(2))}}));try{const done=await api(`/api/boards/${state.board.id}/imports/commit`,'POST',{batch_id:preview.batch_id,batch_version:preview.batch_version,board_version:preview.board_version,group_id:Number($('#importGroup').value),mapping});closeModal('listModal');await refresh();toast(`已导入 ${done.created} 个任务`)}catch(error){showError(error)}};
    }catch(error){showError(error)}
  }
  $('#previewImportBtn').onclick=async()=>{file=$('#importFile').files[0];if(!file)return toast('请选择文件');try{encoded=await fileBase64(file);await runPreview()}catch(error){showError(error)}}
}
async function exportBoard(){
  if(!state.board)return;const format=(prompt('导出格式：csv 或 xlsx','xlsx')||'').toLowerCase();if(!['csv','xlsx'].includes(format))return;
  try{const result=await api(`/api/boards/${state.board.id}/export`,'POST',{format,query:activeQuery,visible_fields:presentedFields().map(field=>field.id)});const bytes=Uint8Array.from(atob(result.content_base64),character=>character.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:result.media_type})),link=document.createElement('a');link.href=url;link.download=result.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`已导出 ${result.row_count} 行`)}catch(error){showError(error)}
}

