function startRealtime(){
  if(realtimeSource)realtimeSource.close();if(!state.current_user||!state.workspace_id)return;realtimeWorkspace=state.workspace_id;$('#realtimeState').textContent='实时连接中';
  const source=new EventSource(`/api/workspaces/${state.workspace_id}/events/stream?cursor=${realtimeCursor}`);realtimeSource=source;
  source.addEventListener('update',event=>{const payload=JSON.parse(event.data);realtimeCursor=payload.cursor||realtimeCursor;realtimeRetry=1000;$('#realtimeState').textContent=`实时 · ${payload.online?.length||1} 在线`;if(!interactionLocked&&FlowboardI12.shouldRefresh(payload.events,state.current_user?.id))refresh(true)});
  source.onopen=()=>{$('#realtimeState').textContent='实时已连接'};source.onerror=()=>{source.close();if(realtimeSource===source)realtimeSource=null;$('#realtimeState').textContent='轮询降级';setTimeout(()=>{if(state.current_user)startRealtime()},realtimeRetry);realtimeRetry=Math.min(realtimeRetry*2,30000)};
}

function syncUrl(){const url=new URL(location.href);selectedBoardId?url.searchParams.set('board',selectedBoardId):url.searchParams.delete('board');activeViewId?url.searchParams.set('view',activeViewId):url.searchParams.delete('view');viewType==='calendar'?url.searchParams.set('month',`${calendarCursor.getFullYear()}-${String(calendarCursor.getMonth()+1).padStart(2,'0')}`):url.searchParams.delete('month');history.replaceState(null,'',url)}
function renderViews(){const select=$('#viewSelect');if(!select)return;const views=state.saved_views||[];select.innerHTML='<option value="">默认视图</option>'+views.map(view=>`<option value="${view.id}" ${view.id===activeViewId?'selected':''}>${view.blocked?'⚠ ':''}${esc(view.name)} (${view.scope==='shared'?'共享':'个人'})</option>`).join('')}
function applySearch(){viewTransition('search');const value=$('#searchInput').value.trim();const children=(activeQuery.filter?.op==='and'?activeQuery.filter.children:[]).filter(item=>!(item.field?.kind==='core'&&item.field?.key==='title'&&item.operator==='contains'));if(value)children.push({field:{kind:'core',key:'title'},operator:'contains',value});activeQuery={...activeQuery,filter:{op:'and',children}};syncUrl();refresh()}
async function configureFilter(){const fields=['title',...(state.fields||[]).filter(field=>field.is_active).map(field=>`${field.id}:${field.name}[${field.field_type}]`)];const raw=prompt(`输入条件 JSON；字段：${fields.join('，')}\n示例：{"field":{"kind":"core","key":"title"},"operator":"contains","value":"设计"}`,'');if(raw===null||!raw.trim())return;try{viewTransition('filter');const condition=JSON.parse(raw);activeQuery={...activeQuery,filter:{op:'and',children:[condition]}};syncUrl();await refresh()}catch(error){showError(error instanceof SyntaxError?new Error('筛选 JSON 无效'):error)}}
