async function openDashboard(id){try{const dashboard=await api(`/api/dashboards/${id}`);openList(`<h2 class="modal-title">${esc(dashboard.name)}</h2><p class="modal-subtitle">${dashboard.scope==='shared'?'共享':'个人'} · ${dashboard.sources.length} 个来源 · ${dashboard.widgets.length} 个组件</p>${dashboard.can_update?'<div class="dashboard-actions"><button class="tool-btn" id="addDashboardSource">＋ 来源</button><button class="tool-btn" id="addDashboardWidget">＋ 组件</button><button class="tool-btn" id="dashboardFilter">全局筛选</button><button class="tool-btn" id="copyDashboard">复制</button><button class="danger-btn" id="deleteDashboard">删除</button></div>':''}<div class="dashboard-sources">${dashboard.sources.map(source=>`<span>${esc(source.source_key)} · 看板 ${source.board_id}</span>`).join('')}</div><div class="dashboard-grid">${dashboard.widgets.map(widgetBody).join('')||'<div class="empty-state compact">添加数字、图表、进度、日历或表格组件</div>'}</div>`);for(const widget of dashboard.widgets)loadWidgetData(dashboard,widget);if(!dashboard.can_update)return;
    $('#addDashboardSource').onclick=async()=>{const sourceKey=prompt('来源标识（跨看板字段需按此显式映射）',`source${dashboard.sources.length+1}`),boardId=Number(prompt('来源看板 ID',state.board?.id||1));if(!sourceKey||!boardId)return;try{await api(`/api/dashboards/${id}/sources`,'POST',{dashboard_version:dashboard.version,source_key:sourceKey,board_id:boardId,query:{version:1,filter:{op:'and',children:[]},sort:[]}});openDashboard(id)}catch(error){showError(error)}};
    $('#addDashboardWidget').onclick=async()=>{const kind=prompt('组件：number / chart / progress / calendar / table','number'),sourceKeys=prompt('来源标识（逗号分隔）',dashboard.sources.map(item=>item.source_key).join(','))?.split(',').map(x=>x.trim()).filter(Boolean),title=prompt('组件标题','新组件');if(!kind||!sourceKeys?.length||!title)return;let config={version:1,source_keys:sourceKeys};if(['number','chart'].includes(kind)){const chartType=kind==='chart'?prompt('图表：bar / line / pie / stacked_bar','bar'):'bar';config.spec={version:1,chart_type:chartType,dimension:{kind:'core',key:kind==='number'?'board':'status'},metric:{op:'count'},date_bucket:chartType==='line'?'month':'none',top_n:20,null_policy:'include'}}else if(kind==='progress')config.complete_values=['已完成'];else if(kind==='calendar'){config.date_field={kind:'core',key:'due'};config.limit=50}else{config.columns=['title','status'];config.limit=50}try{await api(`/api/dashboards/${id}/widgets`,'POST',{dashboard_version:dashboard.version,widget_type:kind,title,config,x:0,y:dashboard.widgets.length*3,width:kind==='number'?3:6,height:3});openDashboard(id)}catch(error){showError(error)}};
    $('#dashboardFilter').onclick=async()=>{const raw=prompt('按来源显式映射的筛选 JSON：{"source1":{"op":"and","children":[]}}',JSON.stringify(dashboard.global_filters.by_source||{}));if(raw===null)return;try{await api(`/api/dashboards/${id}`,'PATCH',{version:dashboard.version,global_filters:{version:1,by_source:JSON.parse(raw)}});openDashboard(id)}catch(error){showError(error)}};$('#copyDashboard').onclick=async()=>{try{const copy=await api(`/api/dashboards/${id}/copy`,'POST',{});openDashboard(copy.id)}catch(error){showError(error)}};$('#deleteDashboard').onclick=async()=>{try{await api(`/api/dashboards/${id}`,'DELETE',{version:dashboard.version});manageDashboards()}catch(error){showError(error)}};
    document.querySelectorAll('[data-widget-move]').forEach(button=>button.onclick=()=>changeWidget(dashboard,+button.dataset.widgetMove,'move'));document.querySelectorAll('[data-widget-resize]').forEach(button=>button.onclick=()=>changeWidget(dashboard,+button.dataset.widgetResize,'resize'));document.querySelectorAll('[data-widget-copy]').forEach(button=>button.onclick=async()=>{const widget=dashboard.widgets.find(item=>item.id===+button.dataset.widgetCopy);try{await api(`/api/dashboards/${id}/widgets/${widget.id}/copy`,'POST',{version:widget.version,dashboard_version:dashboard.version});openDashboard(id)}catch(error){showError(error)}});document.querySelectorAll('[data-widget-delete]').forEach(button=>button.onclick=async()=>{const widget=dashboard.widgets.find(item=>item.id===+button.dataset.widgetDelete);try{await api(`/api/dashboards/${id}/widgets/${widget.id}`,'DELETE',{version:widget.version,dashboard_version:dashboard.version});openDashboard(id)}catch(error){showError(error)}});bindDashboardLayout(dashboard)
  }catch(error){showError(error)}}
async function saveWidgetLayout(dashboard,widget,layout){try{interactionLocked=true;await api(`/api/dashboards/${dashboard.id}/widgets/${widget.id}`,'PATCH',{version:widget.version,dashboard_version:dashboard.version,...FlowboardDashboard.clamp(layout)});openDashboard(dashboard.id)}catch(error){showError(error)}finally{interactionLocked=false}}
async function changeWidget(dashboard,id,mode){const widget=dashboard.widgets.find(item=>item.id===id),raw=prompt(mode==='move'?'新 x,y':'新 width,height',mode==='move'?`${widget.x},${widget.y}`:`${widget.width},${widget.height}`);if(!raw)return;const [a,b]=raw.split(',').map(Number);saveWidgetLayout(dashboard,widget,mode==='move'?{...widget,x:a,y:b}:{...widget,width:a,height:b})}
